const items = [];
const TOTAL_DAYS = 30;

for (let i = 0; i < TOTAL_DAYS; i++) {
  const d = new Date();
  d.setDate(d.getDate() - i);

  // Skip Sundays
  if (d.getDay() !== 0) {
    const yyyy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const dd = String(d.getDate()).padStart(2, '0');
    items.push({
      json: {
        dateStr: `${yyyy}${mm}${dd}`
      }
    });
  }
}

return items;

