const items = [];
const incoming = $input.first()?.json;

// If the request failed or returned empty, emit a dummy record so as not to break the loop
if (!incoming) {
  return [{ json: { skip: true, boe_id: '', url_boe: '' } }];
}

const root = incoming.data || incoming;
const sumario = root.sumario || root;

let diario = null;
if (Array.isArray(sumario.diario)) {
  diario = sumario.diario[0];
} else if (sumario.diario) {
  diario = sumario.diario;
}

if (!diario || !diario.seccion) {
  return [{ json: { skip: true, boe_id: '', url_boe: '' } }];
}

const secciones = Array.isArray(diario.seccion) ? diario.seccion : [diario.seccion];

// Official sections where grants/aid are published: III and V-B
const ALLOWED_SECTIONS = ['3', '5B'];

// Mandatory terms for grants/aid
const STRICT_GRANT_REGEX = /\b(subvenci[oó]n|subvenciones|ayuda|ayudas|beca|becas)\b/i;

// Standard noise exclusion
const EXCLUDE_REGEX = /extrav[ií]o de t[ií]tulo|duplicado de t[ií]tulo|recurso contencioso|licitaci[oó]n|formalizaci[oó]n de contrato/i;

for (const sec of secciones) {
  if (!sec || !sec.codigo || !ALLOWED_SECTIONS.includes(String(sec.codigo))) continue;
  if (!sec.departamento) continue;

  const depts = Array.isArray(sec.departamento) ? sec.departamento : [sec.departamento];

  for (const dept of depts) {
    if (!dept || !dept.item) continue;
    const rows = Array.isArray(dept.item) ? dept.item : [dept.item];

    for (const item of rows) {
      const titulo = item.titulo || '';

      if (STRICT_GRANT_REGEX.test(titulo) && !EXCLUDE_REGEX.test(titulo) && item.identificador) {
        let perfil = 'General';
        if (/pyme|pymes|empresas|emprendedor|startup|comercio|competitividad/i.test(titulo)) perfil = 'Pymes';
        else if (/aut[oó]nomo|cuenta propia|trabajador aut[oó]nomo/i.test(titulo)) perfil = 'Autónomos';
        else if (/estudiante|alumn|investigad|predoctoral|postdoctoral|beca|formaci[oó]n/i.test(titulo)) perfil = 'Estudiantes e Investigadores';
        else if (/agricult|ganader|rural|pesca/i.test(titulo)) perfil = 'Sector Primario';

        const moneyMatch = titulo.match(/\d+([.,]\d+)*\s*(€|euros)/i);

        items.push({
          json: {
            skip: false,
            boe_id: item.identificador,
            titulo_limpio: titulo,
            organo: dept.nombre || 'Administración Pública',
            perfil: perfil,
            cuantia_previa: moneyMatch ? moneyMatch[0] : null,
            url_boe: item.url_html || `https://www.boe.es/diario_boe/txt.php?id=${item.identificador}`
          }
        });
      }
    }
  }
}

if (items.length === 0) {
  return [{ json: { skip: true, boe_id: '', url_boe: '' } }];
}

return items;

const prev = $('Code: Filter Grants').item.json;
const aiRaw = $input.item.json;

// Si el día venía marcado para omitir
if (prev.skip || !prev.boe_id) {
  return {
    skip: true,
    boe_id: '',
    titulo_limpio: '',
    organo: '',
    perfil: '',
    cuantia: '',
    fecha_limite: '',
    requisitos: '[]',
    url_boe: ''
  };
}

let parsed = {
  cuantia: prev.cuantia_previa || 'Consultar bases reguladoras',
  fecha_limite: 'Consultar plazo en bases oficiales',
  requisitos: ['Cumplir condiciones fijadas en la sede electrónica del órgano convocante.']
};

try {
  const content = aiRaw.text || aiRaw.response?.text || aiRaw.output || aiRaw;
  const match = typeof content === 'string' ? content.match(/\{[\s\S]*\}/) : null;
  if (match) {
    const data = JSON.parse(match[0]);
    if (data.cuantia) parsed.cuantia = data.cuantia;
    if (data.fecha_limite) parsed.fecha_limite = data.fecha_limite;
    if (Array.isArray(data.requisitos) && data.requisitos.length > 0) {
      parsed.requisitos = data.requisitos;
    }
  }
} catch (e) {
  // Mantener valores de respaldo si el parseo falla
}

return {
  skip: false,
  boe_id: prev.boe_id,
  titulo_limpio: prev.titulo_limpio,
  organo: prev.organo,
  perfil: prev.perfil,
  cuantia: String(parsed.cuantia).slice(0, 250),
  fecha_limite: String(parsed.fecha_limite).slice(0, 250),
  requisitos: JSON.stringify(parsed.requisitos),
  url_boe: prev.url_boe
};
